(6790479, 1017991, 69668, '<td valign="top">Cool image....I like the ones you sent me as well.  I remember the first one the best.....moody, dark, black and white...with great expression.  This is completely opposite, which is great variety for a senior.  Nice touch of whimsy with the flying tie.</td>', 'Cool image....I like the ones you sent me as well.  I remember the first one the best.....moody, dark, black and white...with great expression.  This is completely opposite, which is great variety for a senior.  Nice touch of whimsy with the flying tie.', '2012-06-08 12:02:33.000000', NULL, 0),
(6790481, 1014100, 47906, '<td valign="top">Hey Tj, Great shot of Olde Orchard. I was wondering whose this was. Excellent capture! I gave it an 8. We should get together and shoot sometime. I am up in Maine often these days =)</td>', 'Hey Tj, Great shot of Olde Orchard. I was wondering whose this was. Excellent capture! I gave it an 8. We should get together and shoot sometime. I am up in Maine often these days =)', '2012-06-08 12:02:46.000000', NULL, 0),
(6790483, 1015965, 118154, '<td valign="top">Congrats John,I think I remember saying those words before.</td>', 'Congrats John,I think I remember saying those words before.', '2012-06-08 12:04:39.000000', NULL, 0),
(6790486, 1018676, 118154, '<td valign="top">Fantastic finish, Congratulations,thanks for the processing steps.</td>', 'Fantastic finish, Congratulations,thanks for the processing steps.', '2012-06-08 12:07:11.000000', NULL, 0),
(6790490, 1017662, 22970, '<td valign="top">Congratulations, such grace in flight!</td>', 'Congratulations, such grace in flight!', '2012-06-08 12:13:54.000000', NULL, 0),
