(6790495, 1015965, 112739, '<td valign="top">Been reading the reviews of the Fuji X-Pro 1. Mostly they talk about slow AF and difficult MF most of the time leading to missed opportunities. You do not seem to have any issues with catching the right moment with this camera! Congratulations on the Yellow in this FS.</td>', 'Been reading the reviews of the Fuji X-Pro 1. Mostly they talk about slow AF and difficult MF most of the time leading to missed opportunities. You do not seem to have any issues with catching the right moment with this camera! Congratulations on the Yellow in this FS.', '2012-06-08 12:27:27.000000', NULL, 0),
(6790496, 1017662, 138630, '<td valign="top">Oh, my, the light, the light.  And the detail.  And the moment captured.  One of my 10''s and a well deserved blue, Wendy.</td>', 'Oh, my, the light, the light.  And the detail.  And the moment captured.  One of my 10''s and a well deserved blue, Wendy.', '2012-06-08 12:33:06.000000', NULL, 0),
(6790498, 1017662, 19825, '<td valign="top">Such a lovely shot. Luminescent against the dark background. You are the master.</td>', 'Such a lovely shot. Luminescent against the dark background. You are the master.', '2012-06-08 12:34:33.000000', NULL, 0),
(6790499, 1016787, 138630, '<td valign="top">Another fantastic bird capture - spread wings, great detail and light, and the added interest of that dragonfly - WOW.  Congratulations on the Red.  One of my 10''s.</td>', 'Another fantastic bird capture - spread wings, great detail and light, and the added interest of that dragonfly - WOW.  Congratulations on the Red.  One of my 10''s.', '2012-06-08 12:35:06.000000', NULL, 0),
(6790502, 1015965, 19825, '<td valign="top">Another visual treat. I am thinking you may have some talent for this photography stuff. Great job.</td>', 'Another visual treat. I am thinking you may have some talent for this photography stuff. Great job.', '2012-06-08 12:37:21.000000', NULL, 0),
